// Generated by scripts/build-glossary-data.mjs from content-source/glossary. Do not edit by hand.
export const GLOSSARY_SHARD = Object.freeze({"bitcoin-halving":{"slug":"bitcoin-halving","cat":"basics","en":"Bitcoin halving","contentLocale":"es","term":"Halving de Bitcoin","aka":["halving","halvening","reducción a la mitad"],"short":"El halving de Bitcoin es el evento programado en el protocolo que, cada 210.000 bloques (unos cuatro años), reduce a la mitad la recompensa que reciben los mineros por cada bloque nuevo.","body":[["Cuando ",["Bitcoin","bitcoin"]," arrancó en 2009, cada bloque emitía 50 BTC nuevos. Tras los halvings de 2012, 2016, 2020 y abril de 2024, la recompensa es hoy de 3,125 BTC por bloque. Así, la emisión se frena cada vez más hasta acercarse al límite de 21 millones."],["Para los mineros, el halving reduce a la mitad sus ingresos en BTC de un día para otro. Los menos eficientes pueden apagar máquinas si el precio y las comisiones no compensan, lo que influye en el ",["hash rate","hash-rate"]," de la red."],["Mucha gente asocia los halvings con ciclos de mercado. Ha habido subidas fuertes después de algunos halvings, pero el precio depende de muchos otros factores, como la ",["liquidez","liquidity"]," global o la demanda de ETF, así que no lo tomes como un mecanismo automático."]],"example":"Bitcoin produce de media un bloque cada 10 minutos, unos 144 al día. Antes del halving de 2024, con 6,25 BTC por bloque, se emitían unos 900 BTC diarios. Después, con 3,125 BTC, se emiten unos 450 BTC diarios. Si un minero tenía el 1 % del hash rate, pasaba de ganar unos 9 BTC al día a unos 4,5 BTC, más las comisiones, con el mismo gasto en electricidad.","mistakes":["Dar por hecho que el precio subirá justo después del halving.","Pensar que el halving reduce a la mitad los bitcoins que ya tienes.","Confundir la fecha exacta: el halving ocurre por número de bloque, no en un día fijo del calendario."],"faq":[{"q":"¿Cuándo es el próximo halving de Bitcoin?","a":"Ocurre cada 210.000 bloques, así que tras el de abril de 2024 el siguiente se espera hacia 2028. La fecha exacta depende de la velocidad de producción de bloques."},{"q":"¿Qué pasa cuando se minen los 21 millones?","a":"Los mineros dejarán de recibir BTC nuevos y vivirán solo de las comisiones de transacción. Eso se estima para alrededor del año 2140."}],"title":"¿Qué es el halving de Bitcoin? Cómo funciona","description":"Qué es el halving de Bitcoin, cada cuánto ocurre, cómo reduce la recompensa de los mineros y qué cambió con el halving de abril de 2024.","related":[["bitcoin","Bitcoin (BTC)","Bitcoin (BTC) es la primera criptomoneda, lanzada en 2009, con un suministro máximo de 21 millones de unidades y una red descentralizada que funciona con prueba de trabajo."],["mining","Minería de criptomonedas","La minería de criptomonedas es el proceso por el que equipos especializados aportan potencia de cálculo a una red de prueba de trabajo para validar transacciones, crear nuevos bloques y cobrar la recompensa en monedas nuevas y comisiones."],["proof-of-work","Prueba de trabajo (proof of work, PoW)","La prueba de trabajo (PoW) es un mecanismo de consenso en el que los mineros gastan potencia de cálculo y electricidad para resolver un problema criptográfico y ganar el derecho a añadir el siguiente bloque."],["hash-rate","Tasa de hash (hash rate)","La tasa de hash es la potencia de cálculo total que los mineros dedican a una red de prueba de trabajo, medida en hashes por segundo, como Bitcoin en EH/s."],["satoshi","Satoshi (sats)","Un satoshi (sat) es la unidad más pequeña de bitcoin: 1 BTC equivale a 100.000.000 satoshis, y el nombre rinde homenaje a Satoshi Nakamoto, el creador de Bitcoin."]],"lesson":null,"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"stop-loss":{"slug":"stop-loss","cat":"trading","en":"Stop-loss order","contentLocale":"es","term":"Stop loss (orden de stop)","aka":["stop loss","SL","orden stop","límite de pérdidas"],"short":"Un stop loss es una orden que cierra automáticamente tu posición cuando el precio llega a un nivel que has fijado, para limitar la pérdida si el mercado va en tu contra.","body":[["Defines un precio de activación (stop). Mientras el precio no lo toque, la orden no hace nada. Cuando lo toca, el exchange envía una ",["orden de mercado","market-order"]," (stop market) o una ",["orden límite","limit-order"]," (",["stop limit","stop-limit-order"],") para cerrar la posición. En futuros, puedes elegir si la activación usa el ",["último precio","last-price"]," o el ",["precio de marca","mark-price"],"."],["El stop loss convierte una pérdida potencialmente ilimitada en una pérdida planificada. Sirve también para calcular el tamaño de la posición: si sabes dónde saldrás, sabes cuánto arriesgas. En futuros, un buen stop te saca antes de llegar al ",["precio de liquidación","liquidation-price"],"."],"No es infalible. En caídas muy rápidas, un stop de mercado puede ejecutarse peor de lo previsto por deslizamiento, y un stop limit puede quedarse sin ejecutar. Colocarlo demasiado cerca hace que el ruido normal del mercado te saque."],"example":"Supón que compras 1.000 USDT de un token a 2,00 USDT (500 unidades) y pones un stop loss en 1,84, un 8 % abajo. Si el precio cae a 1,84, la orden se activa y vendes a mercado. Si se ejecuta a 1,83 por deslizamiento, recibes 915 USDT: pierdes 85 USDT en lugar de los 80 previstos. Sin stop, si el precio llega a 1,40, la pérdida habría sido de 300 USDT.","mistakes":["Mover el stop loss más abajo cada vez que el precio se acerca para \"darle más espacio\".","Ponerlo tan cerca que una oscilación normal te saca de la operación.","Abrir futuros apalancados sin stop loss y confiar en que la liquidación sea tu salida."],"faq":[{"q":"¿Dónde poner el stop loss?","a":"Donde tu idea de la operación deja de ser válida, por ejemplo bajo un soporte claro, y no a un porcentaje arbitrario. Luego ajusta el tamaño de la posición para que esa pérdida sea asumible."},{"q":"¿El stop loss garantiza el precio de salida?","a":"No. Un stop de mercado garantiza la ejecución pero no el precio, y un stop limit garantiza el precio pero no la ejecución."}],"title":"¿Qué es un stop loss en cripto? Cómo funciona","description":"Qué es un stop loss, cómo se activa, diferencias entre stop market y stop limit, y cómo usarlo para limitar pérdidas en cripto.","related":[["take-profit","Take profit (toma de beneficios)","Un take profit (TP) es una orden que cierra automáticamente tu posición, total o parcialmente, cuando el precio alcanza un objetivo de ganancia que has fijado de antemano."],["stop-limit-order","Orden stop limit","Una orden stop limit combina dos precios: un precio de activación (stop) que, al alcanzarse, coloca automáticamente una orden límite a un precio que tú fijas, de modo que controlas el peor precio aceptable."],["trailing-stop","Trailing stop (stop dinámico)","Un trailing stop es una orden de stop que sigue al precio a una distancia fija, en porcentaje o en importe, cuando el mercado se mueve a tu favor, y que se activa si el precio retrocede esa distancia desde el mejor nivel alcanzado."],["position-sizing","Tamaño de posición","El tamaño de posición es la cantidad de capital que asignas a una operación, calculada para que, si toca tu stop loss, pierdas solo un porcentaje fijo de tu cuenta."],["liquidation","Liquidación","La liquidación es el cierre forzoso de una posición apalancada por parte del exchange cuando tu margen ya no cubre el margen de mantenimiento exigido."]],"lesson":{"id":"E17","slug":"stop-loss-is-a-plan","ep":17,"title":"Take-profit y stop-loss son planes, no seguros"},"coin":null,"tool":"/liquidations","cta":false},"unrealized-pnl":{"slug":"unrealized-pnl","cat":"derivatives","en":"Unrealized PnL","contentLocale":"es","term":"PnL no realizado","aka":["ganancia no realizada","pérdida no realizada","unrealized PnL","PnL flotante"],"short":"El PnL no realizado es la ganancia o pérdida de una posición que sigue abierta, calculada con el precio actual, y que solo se vuelve real cuando cierras la posición.","body":["PnL significa profit and loss, ganancias y pérdidas. Mientras la posición está abierta, el resultado cambia con cada movimiento de precio: es no realizado o flotante. Cuando cierras total o parcialmente, esa parte pasa a ser PnL realizado y se suma o resta de tu saldo.",["En futuros, el exchange calcula el PnL no realizado con el ",["precio de marca","mark-price"],", no con el ",["último precio","last-price"],". Por eso puede diferir un poco de lo que esperas mirando el gráfico. Algunos exchanges muestran también el ROE o rentabilidad sobre el margen, que exagera el porcentaje cuando usas ",["apalancamiento","leverage"],"."],["En ",["margen cruzado","cross-margin"],", las ganancias no realizadas suelen contar como garantía para otras posiciones, y las pérdidas no realizadas reducen tu margen disponible. Una ganancia flotante grande puede desaparecer rápido si no cierras o proteges la posición con un ",["take profit","take-profit"]," o un ",["stop loss","stop-loss"],"."]],"example":"Abres un largo de 0,2 BTC a 55.000 USDT. El precio de marca sube a 58.000: tu PnL no realizado es 0,2 × 3.000 = +600 USDT. Cierras la mitad, 0,1 BTC, a 58.000: realizas 300 USDT, que pasan a tu saldo. Los otros 300 siguen siendo no realizados. Si el precio vuelve a 55.000, esa mitad abierta regresa a 0, pero los 300 realizados ya son tuyos, menos comisiones.","mistakes":["Contar como ganancia segura un PnL no realizado alto sin cerrar ni proteger la posición.","Confundir el ROE apalancado con el porcentaje real de movimiento del precio.","Olvidar que en margen cruzado una pérdida flotante reduce el margen de todas tus posiciones."],"faq":[{"q":"¿Qué diferencia hay entre PnL realizado y no realizado?","a":"El no realizado es el resultado de una posición todavía abierta. El realizado es el que queda fijado en tu saldo al cerrar total o parcialmente."},{"q":"¿Se pagan impuestos por ganancias no realizadas?","a":"En la mayoría de países se tributa al realizar la ganancia, pero las reglas fiscales varían según el país y el tipo de producto."}],"title":"¿Qué es el PnL no realizado en trading cripto?","description":"Qué es el PnL no realizado, en qué se diferencia del realizado y cómo afecta a tu margen en futuros cripto.","related":[["mark-price","Precio de marca","El precio de marca es un precio de referencia que calculan los exchanges de futuros a partir del índice spot y otros datos, y que usan para calcular la ganancia no realizada y las liquidaciones."],["cross-margin","Margen cruzado","El margen cruzado es un modo en el que todo el saldo disponible de tu cuenta de futuros o margen sirve de garantía compartida para todas tus posiciones abiertas."],["liquidation-price","Precio de liquidación","El precio de liquidación es el precio de marca al que el exchange cerrará de forma forzosa tu posición apalancada porque tu margen habrá bajado al nivel de mantenimiento."],["take-profit","Take profit (toma de beneficios)","Un take profit (TP) es una orden que cierra automáticamente tu posición, total o parcialmente, cuando el precio alcanza un objetivo de ganancia que has fijado de antemano."]],"lesson":{"id":"E20","slug":"maintenance-margin","ep":20,"title":"¿Por qué puedes ser cerrado antes de que tu margen llegue a cero?"},"coin":null,"tool":null,"cta":false},"cold-wallet":{"slug":"cold-wallet","cat":"wallets-security","en":"Cold wallet (cold storage)","contentLocale":"es","term":"Billetera fría (almacenamiento en frío)","aka":["cold wallet","cold storage","almacenamiento en frío","monedero frío"],"short":"Una billetera fría es una forma de guardar cripto en la que las claves privadas se mantienen fuera de cualquier dispositivo conectado a internet, lo que reduce mucho el riesgo de robo remoto.","body":[["La idea es sencilla: si la ",["clave privada","private-key"]," nunca toca internet, un hacker a distancia no puede copiarla. Las formas más comunes son las billeteras de hardware, que firman dentro de un chip aislado, y los equipos dedicados que nunca se conectan a la red."],"Para gastar desde una billetera fría, preparas la transacción en un dispositivo conectado, la firmas en el dispositivo frío y la envías ya firmada. Es más lento, por eso se usa para ahorros de largo plazo y no para operar varias veces al día.",["Los exchanges también usan almacenamiento en frío para la mayor parte de los depósitos de sus clientes, y suelen describirlo en sus páginas de seguridad. El punto débil de una billetera fría suele ser físico: la pérdida del dispositivo, un incendio o una ",["frase semilla","seed-phrase"]," mal guardada."]],"example":["Supón que acumulas 0,2 ",["BTC","bitcoin"]," durante dos años comprando 50 ",["USDT","usdt"]," cada semana. Cada tres meses retiras lo acumulado del exchange a tu ",["billetera de hardware","hardware-wallet"],". Antes de mover un monto grande, envías primero 0,001 BTC de prueba y compruebas que llegan a la dirección que muestra la pantalla del dispositivo. Así, si el exchange sufriera un problema, tus 0,2 BTC seguirían bajo tu control, y la frase semilla estaría anotada en papel en dos lugares distintos."],"mistakes":["Fotografiar la frase semilla de la billetera fría, lo que la convierte de nuevo en información en línea.","Guardar la única copia de la frase junto al dispositivo, de modo que un robo o un incendio se lleva ambas.","Comprar la billetera de hardware de segunda mano o en un vendedor no oficial."],"faq":[{"q":"¿Una billetera fría es lo mismo que una billetera de hardware?","a":"No exactamente. La billetera de hardware es la forma más común de almacenamiento en frío, pero también puede ser un equipo aislado o una configuración multifirma guardada sin conexión."},{"q":"¿Puedo perder mis cripto si se rompe la billetera fría?","a":"No, si conservas la frase semilla. Con ella puedes restaurar las mismas claves en otro dispositivo compatible."}],"title":"¿Qué es una billetera fría? Almacenamiento en frío","description":"Qué es una billetera fría, cómo funciona el almacenamiento en frío y cuándo conviene usarlo frente a una hot wallet.","related":[["hot-wallet","Billetera caliente (hot wallet)","Una billetera caliente (hot wallet) es una billetera cripto cuyas claves se usan en un dispositivo conectado a internet, lo que la hace cómoda para operar a diario pero más expuesta a ataques."],["hardware-wallet","Billetera de hardware","Una billetera de hardware es un dispositivo físico, del tamaño de un USB, que guarda las claves privadas en un chip aislado y firma las transacciones sin exponerlas al computador o al teléfono."],["seed-phrase","Frase semilla (frase de recuperación)","Una frase semilla es una lista de 12 o 24 palabras que permite regenerar todas las claves privadas de una billetera, por lo que quien la tenga controla todos sus fondos."],["multisig-wallet","Billetera multifirma (multisig)","Una billetera multifirma es una billetera que necesita varias firmas de claves distintas, por ejemplo 2 de 3, para aprobar una transacción, en lugar de una sola clave privada."]],"lesson":{"id":"E03","slug":"exchange-vs-wallet","ep":3,"title":"¿Dónde están mis monedas? Exchange vs billetera"},"coin":null,"tool":null,"cta":false},"rug-pull":{"slug":"rug-pull","cat":"wallets-security","en":"Rug pull","contentLocale":"es","term":"Rug pull","aka":["tirón de alfombra","estafa de salida","exit scam"],"short":"Un rug pull es una estafa en la que los creadores de un token o proyecto retiran la liquidez o venden de golpe sus tokens y desaparecen, dejando a los inversores con activos casi sin valor.","body":[["La versión más común ocurre en ",["DEX","dex"],": el creador lanza un token, lo empareja con ",["ETH","ethereum"],", SOL o ",["USDT","usdt"]," en un ",["pool de liquidez","liquidity-pool"]," y lo promociona. Cuando suficientes compradores entran, retira el pool y el precio se desploma porque ya no hay contraparte con la que vender."],"Hay variantes. En un rug \"lento\", el equipo vende poco a poco sus tokens. En otras, el contrato incluye funciones ocultas que impiden vender, permiten crear tokens sin límite o cobran comisiones de venta del 100 %, lo que se conoce como honeypot.",["Señales de alerta: ",["liquidez","liquidity"]," no bloqueada, una ",["billetera","crypto-wallet"]," del equipo con gran parte del suministro, contrato sin verificar, promesas de rentabilidad garantizada y mucha publicidad pagada sin producto real. Ninguna señal aislada lo confirma, pero varias juntas son motivo para no entrar."]],"example":"Un token nuevo se lanza con un pool de 50 ETH y 1.000.000 de tokens. Tú compras con 1 ETH y recibes unos 19.600 tokens. Días después, el pool tiene 120 ETH por las compras de otros. El creador retira toda su liquidez y se lleva esos 120 ETH. Queda un pool casi vacío, y si intentas vender tus 19.600 tokens, apenas obtienes una fracción mínima de ETH. Tu pérdida es prácticamente el 1 ETH completo.","mistakes":["Comprar un token solo porque su precio subió mucho en pocas horas.","No comprobar si la liquidez está bloqueada y quién controla el contrato.","Confiar en que el proyecto es serio porque tiene muchos seguidores en redes sociales."],"faq":[{"q":"¿Un rug pull es ilegal?","a":"En muchos países puede ser fraude, pero la persecución depende de la jurisdicción y de que se pueda identificar a los responsables, que suelen ser anónimos."},{"q":"¿Cómo saber si un token puede hacer rug pull?","a":"Revisa si el contrato está verificado, si la liquidez está bloqueada, cómo se reparte el suministro y si hay funciones que limiten la venta."}],"title":"¿Qué es un rug pull en cripto? Cómo detectarlo","description":"Qué es un rug pull, cómo los creadores retiran la liquidez de un token y qué señales de alerta revisar antes de comprar.","related":[["memecoin","Memecoin","Una memecoin es una criptomoneda inspirada en un meme, un animal o una broma de internet, cuyo precio depende casi por completo de la atención en redes sociales y de la comunidad más que de una utilidad concreta."],["liquidity-pool","Pool de liquidez","Un pool de liquidez es un contrato inteligente que guarda reservas de dos o más tokens para que otros usuarios puedan intercambiarlos, a cambio de comisiones que reciben quienes aportaron esos fondos."],["token-approval","Aprobación de tokens (allowance)","Una aprobación de tokens es un permiso que firmas en tu billetera para que un contrato inteligente pueda mover una cantidad determinada de un token tuyo sin pedirte firma cada vez."],["dex","Exchange descentralizado (DEX)","Un exchange descentralizado (DEX) es una plataforma de intercambio de cripto que funciona con contratos inteligentes, donde operas directamente desde tu billetera sin entregar la custodia de tus fondos."]],"lesson":{"id":"E11","slug":"scam-red-flags","ep":11,"title":"Alguien dice que te hará ganar dinero. Primero mira qué te pide."},"coin":null,"tool":"/topics/meme-coins","cta":false},"oracle":{"slug":"oracle","cat":"defi","en":"Blockchain oracle","contentLocale":"es","term":"Oráculo blockchain","aka":["oráculo","oracle","oráculo de precios"],"short":"Un oráculo blockchain es un servicio que lleva datos externos, como el precio de un activo, a los contratos inteligentes, que por sí solos no pueden consultar información fuera de la cadena.","body":[["Los contratos inteligentes solo ven lo que está en su ",["blockchain","blockchain"],". Para saber cuánto vale ",["ETH","ethereum"]," en dólares, un ",["protocolo de préstamos","defi-lending"]," necesita que alguien publique ese precio en la cadena. Chainlink es la red de oráculos más conocida; Pyth es otro ejemplo muy usado."],"Los oráculos más robustos agregan precios de muchas fuentes y los publican cuando el precio cambia más de cierto umbral o pasa cierto tiempo. De ese precio dependen las liquidaciones, los préstamos y los derivados en cadena.",["Si un oráculo falla o puede manipularse, el protocolo toma decisiones con datos falsos. Muchos ataques ",["DeFi","defi"]," se basaron en oráculos que leían el precio de un solo pool pequeño, fácil de mover con mucho capital. Para un usuario, saber qué oráculo usa un protocolo ayuda a entender cuándo puede ser liquidado."]],"example":["Tienes un préstamo en un protocolo DeFi con umbral de ",["liquidación","liquidation"]," cuando ETH baje de 2.200 ",["USDC","usdc"],". Por un momento, en un exchange pequeño, ETH cae a 2.100 USDC por una venta grande, mientras en el resto del mercado sigue en 2.350 USDC. Si el oráculo agrega muchas fuentes, el precio publicado se mantiene cerca de 2.350 y tu préstamo no se liquida. Si el protocolo leyera solo ese exchange, podrías perder parte de tu garantía."],"mistakes":["Creer que el precio que ves en tu exchange es el mismo que usa el protocolo DeFi para liquidarte.","Ignorar qué oráculo usa un protocolo antes de pedir prestado.","Pensar que un oráculo es solo para precios, cuando también puede aportar otros datos externos."],"faq":[{"q":"¿Qué es Chainlink?","a":"Una red descentralizada de oráculos que publica precios y otros datos para que los usen contratos inteligentes en varias blockchains."},{"q":"¿Por qué los oráculos son un riesgo en DeFi?","a":"Porque si el dato que publican es incorrecto o manipulado, el protocolo puede liquidar posiciones o permitir préstamos con precios falsos."}],"title":"¿Qué es un oráculo blockchain? Chainlink y DeFi","description":"Qué es un oráculo blockchain, cómo lleva precios a los contratos inteligentes y por qué es clave en liquidaciones DeFi.","related":[["smart-contract","Contrato inteligente (smart contract)","Un contrato inteligente (smart contract) es un programa publicado en una blockchain que se ejecuta automáticamente según reglas predefinidas cuando alguien interactúa con él, sin que un intermediario tenga que aprobarlo."],["defi-lending","Préstamos DeFi","Los préstamos DeFi son protocolos en los que depositas cripto para ganar intereses o la usas como garantía para pedir prestados otros tokens, con reglas aplicadas automáticamente por contratos inteligentes."],["index-price","Precio índice","El precio índice es el precio spot de referencia de un activo que calcula un exchange como media ponderada de los precios de varios exchanges spot."],["flash-loan","Préstamo flash (flash loan)","Un préstamo flash (flash loan) es un préstamo sin garantía que debe pedirse y devolverse dentro de la misma transacción de blockchain; si no se devuelve, toda la transacción se revierte como si nunca hubiera ocurrido."]],"lesson":null,"coin":{"slug":"chainlink","name":"Chainlink","symbol":"LINK"},"tool":null,"cta":false},"launchpad":{"slug":"launchpad","cat":"exchange-features","en":"Launchpad (token sale)","contentLocale":"es","term":"Launchpad (venta de tokens)","aka":["launchpad","IEO","venta de tokens","token sale"],"short":"Un Launchpad es una plataforma, normalmente de un exchange, donde puedes comprar tokens de un proyecto nuevo en una venta organizada antes de que empiecen a cotizar en el mercado.","body":["Cuando la venta la organiza un exchange se suele llamar IEO (oferta inicial en exchange). El exchange revisa el proyecto, fija un precio de venta y unas reglas de participación. Muchas veces la asignación depende de cuánto token propio del exchange tienes o de un sorteo.",["Si la demanda supera la oferta, cada participante recibe solo una parte de lo que solicitó y el resto de los fondos se devuelve. Los tokens comprados pueden quedar disponibles al cotizar o liberarse por fases según un calendario de ",["desbloqueo","token-unlock"],"."],"Que un exchange grande organice la venta no garantiza el resultado. El precio al empezar a cotizar puede estar muy por encima o por debajo del de venta. Revisa la valoración total, el porcentaje de tokens en circulación y el calendario de desbloqueos."],"example":["Supón que un Launchpad vende 10.000.000 tokens a 0,05 ",["USDT","usdt"],", un total de 500.000 USDT, y los usuarios solicitan 5.000.000 USDT. La demanda es 10 veces la oferta, así que cada uno recibe el 10 % de lo pedido. Si tú solicitaste 2.000 USDT, recibes 4.000 tokens por 200 USDT y te devuelven 1.800 USDT. Si el token empieza a cotizar a 0,08 USDT, tus tokens valen 320 USDT; si cae a 0,03, valen 120 USDT."],"mistakes":["Pensar que todos los tokens de Launchpad suben al empezar a cotizar.","Ignorar la valoración totalmente diluida y los futuros desbloqueos.","Pedir prestado o vender otros activos con pérdidas solo para participar."],"faq":[{"q":"¿Qué es una IEO?","a":"Una IEO es una venta inicial de tokens organizada por un exchange, que se encarga de la plataforma y de la verificación de los participantes."},{"q":"¿Por qué recibí menos tokens de los que pedí?","a":"Porque la venta estaba sobresuscrita. Cuando la demanda supera la oferta, cada participante recibe una parte proporcional y el resto de los fondos se devuelve."}],"title":"¿Qué es un Launchpad en cripto? Ventas de tokens","description":"Qué es un Launchpad o IEO, cómo se asignan los tokens en una venta de un exchange y qué revisar antes de participar.","related":[["launchpool","Launchpool","Un Launchpool es un producto de exchange en el que bloqueas o depositas ciertos tokens durante unos días y recibes a cambio tokens de un proyecto nuevo antes o justo cuando empieza a cotizar."],["token-listing","Listado de tokens (listing)","El listado de un token es la decisión de un exchange de añadir una criptomoneda a su plataforma para que los usuarios puedan depositarla, comprarla y venderla en uno o varios pares."],["token-unlock","Desbloqueo de tokens (token unlock)","Un desbloqueo de tokens (token unlock) es el momento en que tokens que estaban bloqueados por un calendario de vesting pasan a estar disponibles para sus dueños, normalmente equipo, inversores o tesorería, y pueden venderse."],["airdrop","Airdrop","Un airdrop es una distribución gratuita de tokens que un proyecto envía a ciertas direcciones, normalmente para recompensar a usuarios tempranos, repartir la gobernanza o promocionar un lanzamiento."]],"lesson":null,"coin":null,"tool":"/activities","cta":false},"sub-account":{"slug":"sub-account","cat":"exchange-features","en":"Sub-account","contentLocale":"es","term":"Subcuenta","aka":["subcuenta","sub-account","cuenta secundaria"],"short":"Una subcuenta es una cuenta secundaria dentro de tu cuenta principal de exchange, con saldo y posiciones separadas, que sirve para aislar estrategias, bots o riesgos sin abrir otra cuenta con otro KYC.","body":["La cuenta principal controla las subcuentas: puede crearlas, transferirles fondos y fijar permisos. Cada subcuenta tiene su propio saldo, sus órdenes y sus claves API, y en general comparte el nivel de verificación de la principal.",["Se usan para separar el trading a largo plazo del especulativo, para dar a un bot solo una parte del capital o para probar una estrategia de ",["copy trading","copy-trading"]," sin tocar el resto. Si una subcuenta sufre una ",["liquidación","liquidation"],", las demás no se ven afectadas."],["Las reglas cambian según el exchange: número máximo de subcuentas, si permiten retiros directos, cómo se cuenta el volumen para los niveles VIP. Protege la cuenta principal con ",["autenticación de dos factores","two-factor-authentication"],", porque desde ella se controla todo."]],"example":["Supón que tienes 10.000 ",["USDT","usdt"],". Dejas 7.000 en la cuenta principal para spot, pasas 2.000 a una subcuenta para un bot de futuros y 1.000 a otra para copy trading. Si el bot sufre una liquidación y pierde los 2.000 USDT, tus 7.000 de spot y los 1.000 de copy trading siguen intactos. La pérdida máxima del experimento quedó limitada al 20 % de tu capital."],"mistakes":["Dar a un bot claves API de la cuenta principal en lugar de una subcuenta.","Usar margen cruzado en una cuenta con todo el capital en vez de aislar en subcuentas.","Perder de vista los saldos repartidos y creer que tienes menos fondos de los reales."],"faq":[{"q":"¿Una subcuenta necesita otro KYC?","a":"Normalmente no. Hereda la verificación de la cuenta principal, aunque las reglas exactas dependen del exchange."},{"q":"¿Para qué sirve una subcuenta?","a":"Para separar capital y riesgos: estrategias distintas, bots o pruebas sin afectar al resto de tu saldo."}],"title":"¿Qué es una subcuenta en un exchange cripto?","description":"Qué es una subcuenta en un exchange, para qué sirve separar estrategias y bots, y cómo limita las pérdidas de una prueba.","related":[["unified-trading-account","Cuenta unificada de trading (UTA)","Una cuenta unificada de trading es un tipo de cuenta de exchange que reúne spot, margen y derivados en un solo saldo, de modo que tus activos sirven como margen común para todas las posiciones."],["isolated-margin","Margen aislado","El margen aislado es un modo en el que cada posición tiene su propio margen asignado, de forma que si se liquida solo pierdes ese margen y no el resto del saldo."],["two-factor-authentication","Autenticación de dos factores (2FA)","La autenticación de dos factores (2FA) es una capa de seguridad que exige, además de la contraseña, un segundo código o dispositivo para entrar en tu cuenta o aprobar retiros."],["copy-trading","Copy trading","El copy trading es una función de los exchanges que permite copiar automáticamente las operaciones de otro trader, llamado líder, en tu propia cuenta y en la proporción que elijas."]],"lesson":null,"coin":null,"tool":null,"cta":false},"vip-tier":{"slug":"vip-tier","cat":"exchange-features","en":"VIP fee tier","contentLocale":"es","term":"Nivel VIP de comisiones","aka":["nivel VIP","tier VIP","niveles de comisiones"],"short":"Un nivel VIP de comisiones es un escalón del sistema de tarifas de un exchange que te da comisiones de maker y taker más bajas según tu volumen de trading o el saldo que mantienes.","body":["Los exchanges organizan sus comisiones en niveles: el usuario normal paga la tarifa base y, a medida que aumenta su volumen de 30 días o su saldo de activos, sube de nivel y paga menos. Algunos también cuentan el saldo de su token propio.","Los requisitos y descuentos son distintos en cada exchange y suelen separarse entre spot y futuros. En los niveles más altos, las comisiones maker pueden ser cero o incluso negativas para creadores de mercado. Revisa la tabla oficial de comisiones de tu exchange.",["Para la mayoría de traders minoristas, subir de nivel es difícil. A menudo un ",["código de referido","referral-code"]," o usar más órdenes límite (maker) reduce el coste más que perseguir volumen solo por bajar la comisión."]],"example":["Supón que en un exchange el nivel base cobra 0,10 % taker en spot y el nivel VIP 1 cobra 0,09 % si operas más de 1.000.000 ",["USDT","usdt"]," en 30 días. Si operas 1.200.000 USDT, pagas 1.080 USDT en el nivel VIP 1 en lugar de 1.200 USDT, un ahorro de 120 USDT. Pero si te faltan 100.000 USDT para el nivel y los operas solo para subir, pagas 100 USDT más en comisiones para ahorrar unos 100 USDT: el beneficio prácticamente desaparece."],"mistakes":["Hacer operaciones innecesarias solo para alcanzar un nivel VIP.","Comparar exchanges solo por la tarifa base sin mirar la tabla completa.","Olvidar que spot y futuros suelen tener niveles y volúmenes separados."],"faq":[{"q":"¿Cómo subo de nivel VIP en un exchange?","a":"Normalmente aumentando tu volumen de trading de 30 días o el saldo de activos en la cuenta. Los requisitos exactos están en la página de comisiones de cada exchange."},{"q":"¿El nivel VIP se mantiene para siempre?","a":"No. Se revisa periódicamente, a menudo cada día, según tu volumen y saldo recientes. Si bajan, vuelves a un nivel inferior."}],"title":"¿Qué es un nivel VIP de comisiones en un exchange?","description":"Qué es un nivel VIP en un exchange cripto, cómo se calculan los descuentos en comisiones y cuándo merece la pena subir.","related":[["maker-taker-fees","Comisiones maker y taker","Las comisiones maker y taker son las dos tarifas que cobra un exchange según tu orden añada liquidez al libro de órdenes (maker) o la retire al ejecutarse de inmediato (taker)."],["referral-code","Código de referido (reembolso de comisiones)","Un código de referido es un código que introduces al registrarte en un exchange y que te vincula a quien te invitó, a menudo con un reembolso de parte de tus comisiones de trading o bonos de bienvenida."],["trading-volume","Volumen de trading","El volumen de trading es el valor total de un activo que se ha comprado y vendido en un periodo concreto, normalmente las últimas 24 horas."],["market-maker","Market maker (creador de mercado)","Un market maker o creador de mercado es un participante que publica a la vez órdenes de compra y de venta en un mercado para aportar liquidez y ganar con el spread."]],"lesson":null,"coin":null,"tool":"/rates","cta":false},"token-listing":{"slug":"token-listing","cat":"exchange-features","en":"Token listing","contentLocale":"es","term":"Listado de tokens (listing)","aka":["listing","listado","nuevo listado","token listing"],"short":"El listado de un token es la decisión de un exchange de añadir una criptomoneda a su plataforma para que los usuarios puedan depositarla, comprarla y venderla en uno o varios pares.","body":[["Antes de listar un token, un ",["exchange centralizado","centralized-exchange"]," revisa el proyecto: su equipo, su código, la distribución de tokens, la ",["liquidez","liquidity"],", la demanda de los usuarios y los riesgos legales. Luego anuncia la fecha de apertura de depósitos, el inicio del trading y los pares disponibles, como TOKEN/",["USDT","usdt"],"."],["Un listado en un exchange grande suele aumentar el volumen y la visibilidad, y a menudo provoca movimientos bruscos de precio en las primeras horas. Algunos exchanges listan primero en una zona de innovación o con etiqueta de riesgo, y también existen listados solo en ",["futuros perpetuos","perpetual-futures"],"."],["En los exchanges descentralizados no hay listado oficial: cualquiera puede crear un ",["pool de liquidez","liquidity-pool"]," para un token. Por eso es fácil encontrar tokens falsos con el mismo nombre que uno real. Comprueba siempre la dirección del contrato."]],"example":["Supón que un exchange anuncia el listado de un token con apertura del trading a las 10:00. En los primeros minutos, el precio salta de 0,40 a 0,90 USDT por la demanda, y una hora después baja a 0,55. Si compraste 1.000 tokens a 0,85 con una ",["orden de mercado","market-order"],", pagaste 850 USDT y ahora valen 550: una pérdida de 300 USDT, más de un 35 %. Una orden límite a un precio fijado de antemano te habría evitado comprar en el pico."],"mistakes":["Comprar con orden de mercado en el primer minuto de un listado.","Comprar en un DEX un token con el mismo nombre sin verificar la dirección del contrato.","Creer que estar listado en un exchange grande garantiza la calidad del proyecto."],"faq":[{"q":"¿Qué pasa con el precio cuando un token se lista en un exchange?","a":"Suele haber mucha volatilidad: picos rápidos por la demanda y caídas cuando los primeros compradores venden. No hay un patrón garantizado."},{"q":"¿Cómo se lista un token en un exchange?","a":"El proyecto solicita el listado y el exchange lo evalúa según sus criterios. Cada exchange tiene su propio proceso de revisión."}],"title":"¿Qué es el listado de un token en un exchange?","description":"Qué significa que un exchange liste un token, cómo se evalúa y qué riesgos tiene comprar en las primeras horas de cotización.","related":[["delisting","Deslistado (delisting)","El deslistado es la decisión de un exchange de retirar un token de su plataforma, eliminando sus pares de trading y, tras un plazo, también la posibilidad de depositarlo o retirarlo."],["launchpool","Launchpool","Un Launchpool es un producto de exchange en el que bloqueas o depositas ciertos tokens durante unos días y recibes a cambio tokens de un proyecto nuevo antes o justo cuando empieza a cotizar."],["liquidity","Liquidez","La liquidez es la facilidad con la que puedes comprar o vender un activo rápidamente, en la cantidad que quieres, sin mover mucho su precio."],["altcoin","Altcoin","Una altcoin es cualquier criptomoneda distinta de Bitcoin, desde grandes redes como Ethereum o Solana hasta tokens pequeños y memecoins con poca liquidez."]],"lesson":null,"coin":null,"tool":"/activities","cta":false},"stock-perpetuals":{"slug":"stock-perpetuals","cat":"tokenized-assets","en":"Stock perpetuals","contentLocale":"es","term":"Perpetuos de acciones","aka":["perpetuos sobre acciones","stock perpetuals","futuros perpetuos de acciones"],"short":"Los perpetuos de acciones son contratos de futuros perpetuos que siguen el precio de una acción o un índice bursátil, se liquidan en stablecoins y permiten operar en largo o en corto con apalancamiento.","body":[["Funcionan como los ",["perpetuos","perpetual-futures"]," de cripto: no tienen fecha de vencimiento, usan un ",["precio de índice","index-price"]," y un ",["precio de marca","mark-price"],", y una ",["tasa de financiación","funding-rate"]," periódica mantiene el precio del contrato cerca del de la acción. No compras la acción; solo apuestas a su precio."],"Su particularidad es el horario. La bolsa cierra noches y fines de semana, pero el perpetuo puede seguir operando. En esos periodos, el precio de referencia puede quedar congelado o calcularse de otra forma, y al reabrir la bolsa puede haber saltos bruscos que provoquen liquidaciones.",["Los ofrecen algunos exchanges centralizados y plataformas on-chain, con reglas propias sobre ",["apalancamiento","leverage"],", horario y precio de índice. Revisa la especificación del contrato antes de operar y ten en cuenta que no recibes dividendos ni derechos de accionista."]],"example":["Supón que una acción cotiza a 150 USD y abres un largo de 10 contratos, cada uno equivalente a una acción, con 5x de apalancamiento: posición de 1.500 ",["USDT","usdt"]," y 300 USDT de margen. Si la acción sube a 160, ganas 100 USDT, un 33 % sobre el margen. Si la empresa publica malos resultados tras el cierre y la acción abre a 120, la pérdida sería de 300 USDT: todo tu margen. En la práctica, te liquidarían antes de llegar ahí."],"mistakes":["Ignorar los saltos de precio al reabrir la bolsa tras noches y fines de semana.","Usar apalancamiento alto antes de resultados trimestrales u otras noticias.","Pensar que un perpetuo de acciones da derecho a dividendos."],"faq":[{"q":"¿Qué diferencia hay entre perpetuos de acciones y acciones tokenizadas?","a":"Las acciones tokenizadas están respaldadas por acciones reales. Los perpetuos son derivados con apalancamiento y tasa de financiación, sin acciones detrás."},{"q":"¿Los perpetuos de acciones operan los fines de semana?","a":"Depende de la plataforma. Algunos siguen abiertos con reglas especiales de precio y otros limitan el trading cuando la bolsa está cerrada."}],"title":"¿Qué son los perpetuos de acciones en cripto?","description":"Qué son los perpetuos de acciones, cómo funcionan con apalancamiento y financiación, y qué riesgos hay cuando la bolsa cierra.","related":[["tokenized-stocks","Acciones tokenizadas","Las acciones tokenizadas son tokens en una blockchain que representan acciones de empresas cotizadas y siguen su precio, normalmente respaldadas por acciones reales que guarda un custodio."],["perpetual-futures","Futuros perpetuos (perps)","Los futuros perpetuos son contratos de futuros sin fecha de vencimiento que siguen el precio spot gracias a pagos periódicos entre largos y cortos llamados tasa de financiación."],["funding-rate","Tasa de financiación (funding rate)","La tasa de financiación es un pago periódico entre traders largos y cortos de futuros perpetuos que mantiene el precio del contrato cerca del precio spot."],["leverage","Apalancamiento","El apalancamiento es usar capital prestado para abrir una posición mayor que tu margen, de modo que las ganancias y las pérdidas se multiplican en la misma proporción."]],"lesson":null,"coin":null,"tool":"/topics/tokenized-stocks-vs-perpetuals","cta":true}});
